  name: "各种控件",
  render: () => {
    const [result, setResult] = useState("");
    return <div style={{
      maxWidth: 480
    }}>
        <Form layout="vertical" initialValues={{
        gender: "male",
        notify: true
      }} onFinish={values => setResult(JSON.stringify(values, null, 2))}>
          <Form.Item label="姓名" name="name" required>
            <Input placeholder="请输入" />
          </Form.Item>
          <Form.Item label="性别" name="gender">
            <RadioGroup orientation="horizontal">
              <RadioItem value="male">男</RadioItem>
              <RadioItem value="female">女</RadioItem>
            </RadioGroup>
          </Form.Item>
          <Form.Item label="开启通知" name="notify" valuePropName="checked">
            <Switch />
          </Form.Item>
          <Form.Item label="同意协议" name="agree" valuePropName="checked">
            <Checkbox>我已阅读并同意</Checkbox>
          </Form.Item>
          <Form.Item>
            <Button variant="primary" size="lg" htmlType="submit">
              提交
            </Button>
          </Form.Item>
        </Form>
        {result && <pre style={{
        marginTop: 16,
        fontSize: 12,
        background: "#f5f5f5",
        padding: 12,
        borderRadius: 8
      }}>
            {result}
          </pre>}
      </div>;
  }
